def solve(grid):
    if not grid:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # find distinct non‑zero colours
    colours = set()
    for r in grid:
        for v in r:
            if v:
                colours.add(v)

    if not colours:
        return grid

    # ---------- maximal rectangle for a given colour ----------
    def maximal_rect(colour):
        heights = [0] * cols
        best = None  # (area, top, left, height, width)
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == colour:
                    heights[j] += 1
                else:
                    heights[j] = 0
            stack = []
            for j in range(cols + 1):          # sentinel
                cur_h = heights[j] if j < cols else 0
                while stack and cur_h < heights[stack[-1]]:
                    h = heights[stack.pop()]
                    if stack:
                        w = j - stack[-1] - 1
                        left = stack[-1] + 1
                    else:
                        w = j
                        left = 0
                    area = h * w
                    bottom = i
                    top = bottom - h + 1
                    if best is None or area > best[0]:
                        best = (area, top, left, h, w)
                stack.append(j)
        if best is None:
            return None
        _, top, left, h, w = best
        return (top, left, h, w)

    # compute the biggest axis‑aligned rectangle for each colour
    rects = {}
    for col in colours:
        r = maximal_rect(col)
        if r:
            rects[col] = r   # (top, left, height, width)

    # primary shape – earliest in reading order (smallest top, then left)
    primary = min(colours, key=lambda c: (rects[c][0], rects[c][1]))
    p_top, p_left, p_h, p_w = rects[primary]
    p_minR, p_maxR = p_top, p_top + p_h - 1
    p_minC, p_maxC = p_left, p_left + p_w - 1

    # output grid filled with zeros
    out = [[0] * cols for _ in range(rows)]

    # place primary rectangle (its biggest rectangle stays where it is)
    for r in range(p_top, p_top + p_h):
        for c in range(p_left, p_left + p_w):
            out[r][c] = primary

    # move every other colour's biggest rectangle towards the primary one
    for col in colours:
        if col == primary:
            continue
        top, left, h, w = rects[col]
        o_minR, o_maxR = top, top + h - 1
        o_minC, o_maxC = left, left + w - 1

        # decide whether the gap is vertical or horizontal
        if p_minC <= o_maxC and p_maxC >= o_minC:          # columns overlap → vertical move
            if p_maxR < o_minR:            # primary above
                new_top = p_maxR + 1
                new_left = left
            elif p_minR > o_maxR:          # primary below
                new_top = p_minR - h
                new_left = left
            else:                          # already aligned – keep position
                new_top, new_left = top, left
        else:                                             # horizontal move
            if p_maxC < o_minC:          # primary left of the other
                new_left = p_maxC + 1
                new_top = top
            elif p_minC > o_maxC:        # primary right of the other
                new_left = p_minC - w
                new_top = top
            else:
                new_top, new_left = top, left

        # safety clamp (should never be needed for the given puzzles)
        if new_top < 0:
            new_top = 0
        if new_left < 0:
            new_left = 0
        if new_top + h > rows:
            new_top = rows - h
        if new_left + w > cols:
            new_left = cols - w

        # write the rectangle
        for r in range(new_top, new_top + h):
            for c in range(new_left, new_left + w):
                out[r][c] = col

    return out

